impl crate::ui::Prompter for MockStepDisplay {
    fn prompt(
        &mut self,
        prompt: &crate::ui::Prompt,
    ) -> crate::error::Result<crate::ui::PromptResult> {
        let mut state = self.state.borrow_mut();
        state.prompts_shown.push(prompt.key.clone());

        let is_confirm = matches!(prompt.prompt_type, crate::ui::PromptType::Confirm);
        let is_multiselect = matches!(
            prompt.prompt_type,
            crate::ui::PromptType::MultiSelect { .. }
        );

        // Check queued responses first
        if let Some(queue) = state.prompt_queues.get_mut(&prompt.key) {
            if let Some(response) = queue.pop_front() {
                if is_confirm {
                    let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
                    return Ok(crate::ui::PromptResult::Bool(val));
                }
                if is_multiselect {
                    let values: Vec<String> =
                        response.split(',').map(|s| s.trim().to_string()).collect();
                    return Ok(crate::ui::PromptResult::Strings(values));
                }
                return Ok(crate::ui::PromptResult::String(response));
            }
        }

        // Check pre-configured responses
        if let Some(response) = state.prompt_responses.get(&prompt.key).cloned() {
            if is_confirm {
                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
                return Ok(crate::ui::PromptResult::Bool(val));
            }
            if is_multiselect {
                let values: Vec<String> =
                    response.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(crate::ui::PromptResult::Strings(values));
            }
            return Ok(crate::ui::PromptResult::String(response));
        }

        // Fall back to default_prompt_response
        if let Some(response) = state.default_prompt_response.clone() {
            if is_confirm {
                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
                return Ok(crate::ui::PromptResult::Bool(val));
            }
            if is_multiselect {
                let values: Vec<String> =
                    response.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(crate::ui::PromptResult::Strings(values));
            }
            return Ok(crate::ui::PromptResult::String(response));
        }

        // Fall back to prompt default
        if let Some(default) = &prompt.default {
            if is_confirm {
                let val = matches!(default.as_str(), "true" | "yes" | "y" | "1");
                return Ok(crate::ui::PromptResult::Bool(val));
            }
            if is_multiselect {
                let values: Vec<String> =
                    default.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(crate::ui::PromptResult::Strings(values));
            }
            return Ok(crate::ui::PromptResult::String(default.clone()));
        }

        if is_confirm {
            return Ok(crate::ui::PromptResult::Bool(false));
        }
        if is_multiselect {
            return Ok(crate::ui::PromptResult::Strings(Vec::new()));
        }
        Ok(crate::ui::PromptResult::String(String::new()))
    }
}

