#[test]
fn run_workflow_in_order() {
    let temp = TempDir::new().unwrap();
    let order_file = temp.path().join("order.txt");

    let config: BivvyConfig = serde_yaml::from_str(
        r#"
            workflows:
              default:
                steps: [first, second]
        "#,
    )
    .unwrap();

    let mut steps = HashMap::new();
    steps.insert(
        "first".to_string(),
        make_step(
            "first",
            &format!("echo first >> {}", order_file.display()),
            vec![],
        ),
    );
    steps.insert(
        "second".to_string(),
        make_step(
            "second",
            &format!("echo second >> {}", order_file.display()),
            vec!["first".to_string()],
        ),
    );

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let result = runner
        .run(
