fn make_step(name: &str, command: &str, depends_on: Vec<String>) -> ResolvedStep {
    ResolvedStep {
        name: name.to_string(),
        title: name.to_string(),
        description: None,
        depends_on,
        requires: vec![],
        inputs: HashMap::new(),
        satisfied_when: vec![],
