    assert!(!force.contains("install"));

    let mut steps = HashMap::new();
    steps.insert(
        "install".to_string(),
        make_step_with_check(
            "install",
            "echo install",
            Some(crate::checks::Check::Presence {
                name: None,
                target: Some("install.marker".to_string()),
                kind: Some(crate::checks::PresenceKind::File),
                command: None,
            }),
        ),
    );
