        "build".to_string(),
        make_step_with_check(
            "build",
            "echo build",
            Some(crate::checks::Check::Presence {
                name: None,
                target: Some("build.marker".to_string()),
                kind: Some(crate::checks::PresenceKind::File),
                command: None,
            }),
        ),
    );

    let mut runner = WorkflowRunner::new(&config, steps);
