            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
            None,
            &mut SatisfactionCache::empty(std::path::PathBuf::from(
                "/tmp/bivvy_test_workflow_force_list_sat.json",
