            &mut ui,
            &mut workflow_display,
            &mut EventBus::new(),
        )
        .unwrap();

    assert!(result.success);
    assert_eq!(result.steps.len(), 2);

    // "install" should be check-passed (check satisfied, step not forced)
    // — that path produces a result with check_result populated and the
