    step.requires = vec!["nonexistent-xyz".to_string()];

    let mut steps = HashMap::new();
    steps.insert("hello".to_string(), step);

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let (probe, registry) = make_gap_checker();
    let mut checker = GapChecker::new(&registry, &probe, temp.path());
    // Unknown is not cached — it's the default for unknown requirements
    // But we can pre-cache it for clarity
    checker.seed_cache("nonexistent-xyz", RequirementStatus::Unknown);

    // Non-interactive (default MockUI) → engine skips the step (soft block)
    let mut ui = MockUI::new();

    let mut workflow_display = MockWorkflowDisplay::new();
    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            Some(&mut checker),
            None,
            &mut SatisfactionCache::empty(std::path::PathBuf::from("/tmp/bivvy_test_sat.json")),
            &mut ui,
            &mut workflow_display,
            &mut EventBus::new(),
        )
        .unwrap();

    // Engine decides Skip(RequirementNotMet) — step is skipped, workflow continues
    assert!(!result.steps.is_empty() || !result.skipped.is_empty());
}

