    assert!(!force_all);
    assert!(force.contains("build"));
    assert!(!force.contains("install"));

    let mut steps = HashMap::new();
    steps.insert(
        "install".to_string(),
        make_step_with_check(
            "install",
            "echo install",
            Some(crate::checks::Check::Presence {
