fn hint_shown_on_low_confidence() {
    // A low-confidence pattern match shows a hint in the error block.
    let temp = TempDir::new().unwrap();

    let config: BivvyConfig = serde_yaml::from_str(
        r#"
            workflows:
              default:
                steps: [broken]
        "#,
    )
    .unwrap();

    // "command not found: xyz" triggers the low-confidence command_not_found pattern
    let mut steps = HashMap::new();
    steps.insert(
        "broken".to_string(),
        make_step(
            "broken",
            "echo 'command not found: xyz' >&2; exit 127",
            vec![],
        ),
    );

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let mut ui = MockUI::new();
    // Non-interactive so no recovery menu
    let mut workflow_display = MockWorkflowDisplay::new();
    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
            None,
            &mut SatisfactionCache::empty(std::path::PathBuf::from("/tmp/bivvy_test_sat.json")),
            &mut ui,
            &mut workflow_display,
            &mut EventBus::new(),
        )
        .unwrap();

    assert!(!result.success);
    // Verify hint was passed to show_error_block
    let state = workflow_display.state();
    let blocks = &state.step_error_blocks;
    assert!(!blocks.is_empty());
    let (_, _, hint, _) = &blocks[0];
    assert!(
        hint.is_some(),
        "Expected a hint for 'command not found' pattern"
    );
    assert!(
        hint.as_deref().unwrap().contains("xyz"),
        "Hint should reference the missing command"
    );
}

