    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let (probe, registry) = make_gap_checker();
    let mut checker = GapChecker::new(&registry, &probe, temp.path());
    // Pre-cache as satisfied
    checker.seed_cache("fake-tool", RequirementStatus::Satisfied);

    let mut ui = MockUI::new();

    let mut workflow_display = MockWorkflowDisplay::new();
    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            Some(&mut checker),
