    let config: BivvyConfig = serde_yaml::from_str(
        r#"
            workflows:
              default:
                steps: [broken]
        "#,
    )
    .unwrap();

    let mut steps = HashMap::new();
    steps.insert("broken".to_string(), make_step("broken", "exit 1", vec![]));

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let mut ui = MockUI::new();
    ui.set_interactive(true);
    workflow_display.set_default_prompt_response("yes");
    // First: pick custom_fix, then abort on second prompt
    workflow_display.queue_prompt_responses("recovery_broken", vec!["custom_fix", "abort"]);
    workflow_display.set_prompt_response("custom_fix_broken", "some-fix-cmd");
    // Decline the fix confirmation
    workflow_display.set_prompt_response("confirm_fix_broken", "no");

    let mut workflow_display = MockWorkflowDisplay::new();
    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
