fn make_step_with_check(
    name: &str,
    command: &str,
    check: Option<crate::checks::Check>,
) -> ResolvedStep {
    ResolvedStep {
        name: name.to_string(),
        title: name.to_string(),
        description: None,
        depends_on: vec![],
        requires: vec![],
        inputs: HashMap::new(),
        satisfied_when: vec![],
        execution: ResolvedExecution {
            command: command.to_string(),
            check,
            ..Default::default()
        },
        env_vars: ResolvedEnvironmentVars::default(),
        behavior: ResolvedBehavior::default(),
        hooks: ResolvedHooks::default(),
        output: ResolvedOutput::default(),
        scoping: ResolvedScoping::default(),
    }
}

