fn run_filters_only_environments() {
    let config: BivvyConfig = serde_yaml::from_str(
        r#"
            workflows:
              default:
                steps: [always, ci_only]
        "#,
    )
    .unwrap();

    let mut steps = HashMap::new();
    steps.insert(
        "always".to_string(),
        make_step("always", "echo always", vec![]),
