#[test]
fn recovery_retry_succeeds() {
    // Step fails once, user picks Retry, step succeeds on second attempt.
    let temp = TempDir::new().unwrap();
    let marker = temp.path().join("attempt");

    // Command: create marker on second call (first call fails)
    let cmd = format!(
        "if [ -f {m} ]; then exit 0; else touch {m} && exit 1; fi",
        m = marker.display()
    );

    let config: BivvyConfig = serde_yaml::from_str(
        r#"
            workflows:
              default:
                steps: [flaky]
        "#,
    )
    .unwrap();

    let mut steps = HashMap::new();
    steps.insert("flaky".to_string(), make_step("flaky", &cmd, vec![]));

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let mut ui = MockUI::new();
    ui.set_interactive(true);
    let mut workflow_display = MockWorkflowDisplay::new();
    workflow_display.set_default_prompt_response("yes");
    workflow_display.set_prompt_response("recovery_flaky", "retry");

    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
            None,
            &mut SatisfactionCache::empty(std::path::PathBuf::from("/tmp/bivvy_test_sat.json")),
            &mut ui,
            &mut workflow_display,
            &mut EventBus::new(),
        )
        .unwrap();

    assert!(result.success);
    assert_eq!(result.steps.len(), 1);
    assert!(result.steps[0].success);
    assert_eq!(
        result.steps[0].recovery_detail.as_deref(),
        Some("succeeded on retry (attempt 2)")
    );
}

