            vec!["broken".to_string()],
        ),
    );

    let mut runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let result = runner
        .run(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
        )
        .unwrap();

    // Workflow completed (not Err), but not fully successful
