    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
            None,
            &mut SatisfactionCache::empty(std::path::PathBuf::from("/tmp/bivvy_test_sat.json")),
            &mut ui,
            &mut workflow_display,
            &mut EventBus::new(),
        )
        .unwrap();

    assert!(result.aborted);
    // good + bad should be in results; third should not
    assert_eq!(result.steps.len(), 2);
    let good = result.steps.iter().find(|s| s.name == "good").unwrap();
    let bad = result.steps.iter().find(|s| s.name == "bad").unwrap();
    assert!(good.success);
    assert!(!bad.success);
}

